import { useContext, useState, useEffect } from "react";
import classes from "./UserForm.module.css";
import PasswordContext from "../store/password-context";

const UserForm = ({ onEditItem, editingItem }) => {
  const usePassword = useContext(PasswordContext);
  const [title, setTitle] = useState("");
  const [password, setPassword] = useState("");

  // Populate form fields with editingItem details when it changes
  useEffect(() => {
    if (editingItem) {
      setTitle(editingItem.title);
      setPassword(editingItem.password);
    } else {
      setTitle("");
      setPassword("");
    }
  }, [editingItem]);

  const submitHandler = (event) => {
    event.preventDefault();
    const titleValue = event.target.elements.title.value;
    const passwordValue = event.target.elements.password.value;

    if (editingItem) {
      // Update existing item
      const updatedItem = {
        ...editingItem,
        title: titleValue,
        password: passwordValue,
      };
      onEditItem(updatedItem); // Call onEditItem with the updated item
    } else {
      // Create new item
      const newItem = {
        id: Date.now() + Math.random().toString(36).substring(2),
        title: titleValue,
        password: passwordValue,
      };
      usePassword.addItem(newItem); // Add the new item
    }

    // Reset form fields
    setTitle("");
    setPassword("");
    // Close the form
    usePassword.closeForm();
  };

  const closeFormhandler = () => {
    // Reset form fields
    setTitle("");
    setPassword("");
    // Close the form
    usePassword.closeForm();
  };

  return (
    <div>
      <div className={classes.form}>
        <form onSubmit={submitHandler}>
          <label>Title:</label>
          <input
            type="text"
            name="title"
            value={title}
            onChange={(event) => setTitle(event.target.value)}
            required
          />
          <label>Password:</label>
          <input
            type="text"
            name="password"
            value={password}
            onChange={(event) => setPassword(event.target.value)}
            required
          />

          <button type="submit">{editingItem ? "Save" : "Add"}</button>
          <button type="button" onClick={closeFormhandler}>
            Cancel
          </button>
        </form>
      </div>
    </div>
  );
};

export default UserForm;
